// gate.js — pure decision logic for the /app/* edge gate. Line-for-line port of the store's rule:
//   store/src/middleware.ts gateAppAsset()  +  store/src/lib/entitlementCookie.ts verifyEntitlementCookie()
//   +  store/src/lib/entitlements.ts isActive().  No I/O here so it is unit-testable in Node and identical at the edge.
// Inputs: free-paths.json ({ free: string[], paid_prefixes: [{prefix, code}] }) generated by tools/preview/sync-store.mjs.

export const ENT_COOKIE = 'plp_ent';

export function makeTierRule(freePaths) {
  const FREE_SET = new Set(freePaths.free);
  const PAID = freePaths.paid_prefixes;
  // Returns { kind: 'bad' | 'free' | 'paid' | 'unknown', code? }
  return function classify(rel) {
    if (rel.includes('..') || rel.includes('\\') || rel.includes('\0')) return { kind: 'bad' };
    if (FREE_SET.has(rel)) return { kind: 'free' };
    const owner = PAID.find((p) => rel.startsWith(p.prefix));
    return owner ? { kind: 'paid', code: owner.code } : { kind: 'unknown' };
  };
}

export const isActive = (iso, now = Date.now()) => !!iso && Date.parse(iso) > now;

const enc = new TextEncoder();
const fromB64url = (s) => {
  const t = s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4);
  const bin = atob(t);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
};
const b64url = (bytes) => {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};

async function hmacKey(secret) {
  return crypto.subtle.importKey('raw', enc.encode('plp-ent-v1:' + secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign', 'verify']);
}

// Same format as the store: base64url(JSON {u, e:{XX: iso}, x: expiresAtMs}) "." base64url(HMAC-SHA256(body)).
export async function verifyEntitlementCookie(value, secret, now = Date.now()) {
  if (!value || value.length > 4096 || !secret) return null;
  const [body, sig, extra] = value.split('.');
  if (!body || !sig || extra !== undefined) return null;
  try {
    const key = await hmacKey(secret);
    const okSig = await crypto.subtle.verify('HMAC', key, fromB64url(sig), enc.encode(body));
    if (!okSig) return null;
    const p = JSON.parse(new TextDecoder().decode(fromB64url(body)));
    if (!p || typeof p.u !== 'string' || typeof p.x !== 'number' || p.x <= now || !p.e || typeof p.e !== 'object') return null;
    return p;
  } catch { return null; }
}

// Test helper (never used by the Worker): mint a cookie the way /api/me does.
export async function signEntitlementCookie(payload, secret) {
  const key = await hmacKey(secret);
  const body = b64url(enc.encode(JSON.stringify(payload)));
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(body)));
  return body + '.' + b64url(sig);
}

export function readCookie(header, name) {
  if (!header) return undefined;
  for (const part of header.split(';')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    if (part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return undefined;
}

// Full decision: { status: 200 | 400 | 401 | 403 | 404, error?, state?, tier?: 'free'|'paid' }
export async function decide(rel, cookieHeader, classify, secret, now = Date.now()) {
  const c = classify(rel);
  if (c.kind === 'bad') return { status: 400, error: 'bad_path' };
  if (c.kind === 'free') return { status: 200, tier: 'free' };
  if (c.kind === 'unknown') return { status: 404, error: 'not_found' };
  const ent = await verifyEntitlementCookie(readCookie(cookieHeader, ENT_COOKIE), secret, now);
  if (!ent) return { status: 401, error: 'sign_in_required', state: c.code };
  if (!isActive(ent.e[c.code], now)) return { status: 403, error: 'not_entitled', state: c.code };
  return { status: 200, tier: 'paid', state: c.code };
}
